import sys

def find_pairs(n, k):
    if k == 0:
        return [(i, n - 1 - i) for i in range(n // 2)]
    if k == n - 1:
        return [(0, n - 1)] + [(i, i) for i in range(1, n // 2)]
    return -1

input = sys.stdin.read().strip().split()
t = int(input[0])
index = 1
results = []
for _ in range(t):
    n = int(input[index])
    k = int(input[index + 1])
    index += 2
    pairs = find_pairs(n, k)
    results.append(pairs)

for result in results:
    if result == -1:
        print(-1)
    else:
        for a, b in result:
            print(a, b)
